"""Run the actual finite-shot unary, Dicke, and Max-XORSAT examples."""

from dataclasses import dataclass

import torch

import flagquantum as fq
from flagquantum import synth

from .model import DQI_SHOTS, UNARY_SHOTS, DQIModel, make_model
from .quantum import build_dicke, build_dqi, build_unary


@dataclass(frozen=True)
class Workflow:
    """Actual histograms, oracle reference scores, and the compiled main program."""

    model: DQIModel
    unary: tuple[tuple[int, int], ...]
    dicke_four: tuple[tuple[int, int], ...]
    dicke_two: tuple[tuple[int, int], ...]
    dqi: tuple[tuple[tuple[int, ...], int], ...]
    program: synth.Program
    mean_score: float


def _draw(
    program: synth.Program, registers: tuple[str, ...], shots: int, seed: int
) -> tuple[tuple[tuple[int, ...], int], ...]:
    probabilities = program.probabilities(fq.run(program), registers=registers)
    words = tuple(sorted(probabilities))
    weights = torch.tensor(
        [float(probabilities[word]) for word in words], dtype=torch.float64
    )
    draws = torch.multinomial(
        weights, shots, replacement=True, generator=torch.Generator().manual_seed(seed)
    )
    counts = torch.bincount(draws, minlength=len(words))
    return tuple(
        (word, int(count)) for word, count in zip(words, counts, strict=True) if count
    )


def _single(program: synth.Program, seed: int) -> tuple[tuple[int, int], ...]:
    return tuple(
        (word[0], count)
        for word, count in _draw(program, ("result",), UNARY_SHOTS, seed)
    )


def run_workflow() -> Workflow:
    """Regenerate the source tables, run all four circuits and check the sampled decoder."""
    model = make_model()
    unary = _single(build_unary(), 7)
    dicke_four = _single(build_dicke(4, use_unary=False), 8)
    dicke_two = _single(build_dicke(2, use_unary=True), 9)
    program = build_dqi(model)
    result = _draw(program, ("y", "solution"), DQI_SHOTS, 10)
    if any(word[0] != 0 for word, _ in result):
        raise ValueError("The decoder left a nonzero sampled error word")
    mean = sum(model.objective[word[1]] * count for word, count in result) / DQI_SHOTS
    return Workflow(model, unary, dicke_four, dicke_two, result, program, mean)

"""Reuse the original native DQI kernel with freshly generated classical data."""

from flagquantum import synth
from flagquantum.synth import (
    Output,
    QArray,
    QBit,
    X,
    allocate,
    inplace_prepare_amplitudes,
    qfunc,
)

from ..main import main, symmetric_amplitudes
from .model import SIGNS, DQIModel, dicke_amplitudes


@qfunc
def unary_state(count: int, result: Output[QArray[QBit]]) -> None:
    allocate(15, result)
    for bit in range(count):
        X(result[bit])


@qfunc
def dicke_state(
    unary_weight: int, values: list[float], result: Output[QArray[QBit]]
) -> None:
    allocate(6, result)
    for bit in range(unary_weight):
        X(result[bit])
    apply_dicke_to_unary(unary_weight, values, result)


@qfunc
def apply_dicke_to_unary(
    unary_weight: int, values: list[float], target: QArray[QBit]
) -> None:
    for bit in range(unary_weight):
        X(target[bit])
    inplace_prepare_amplitudes(values, 0, target)


def build_unary(count: int = 8) -> synth.Program:
    """Prepare the source's 15-bit unary word for an admitted classical count."""
    if type(count) is not int or not 0 <= count <= 15:
        raise ValueError("The unary count must be an integer in 0..15")
    return synth.synthesize(
        unary_state, classical_inputs={"count": count}, max_qubits=15, max_workspace=0
    )


def build_dicke(weight: int, *, use_unary: bool) -> synth.Program:
    """Prepare either the direct or known-unary six-bit source example."""
    return synth.synthesize(
        dicke_state,
        classical_inputs={
            "unary_weight": weight if use_unary else 0,
            "values": dicke_amplitudes(weight),
        },
        max_qubits=6,
        max_workspace=0,
    )


def build_dqi(model: DQIModel) -> synth.Program:
    """Evaluate the coherent encoder and decoder for the fresh source incidence table."""
    return synth.synthesize(
        main,
        classical_inputs={
            "amplitudes": symmetric_amplitudes(model.weights),
            "matrix": model.matrix,
            "signs": SIGNS,
            "syndrome_bits": tuple(
                word >> bit & 1 for word, _ in model.syndrome_table for bit in range(6)
            ),
            "mask_bits": tuple(
                mask >> bit & 1 for _, mask in model.syndrome_table for bit in range(6)
            ),
        },
        max_qubits=15,
        max_workspace=3,
        memory_limit_bytes=64 * 1024**2,
    )

"""Native symmetric-weight state, GF(2) encoding and coherent DQI decoding."""

import math

import flagquantum as fq
from flagquantum import synth
from flagquantum.synth import (
    CX,
    H,
    Output,
    QArray,
    QBit,
    X,
    allocate,
    control,
    inplace_prepare_amplitudes,
    phase,
    qfunc,
)

from .data import PARITY_COLUMNS, SIGNS, SYNDROME_TABLE, WEIGHTS


@qfunc
def gf2_product(matrix: list[int], y: QArray[QBit], solution: QArray[QBit]) -> None:
    for row in range(6):
        for column in range(6):
            if matrix[6 * row + column] == 1:
                CX(y[column], solution[row])


@qfunc
def controlled_flip(syndrome: QArray[QBit], target: QBit) -> None:
    control(syndrome, lambda: X(target))


@qfunc
def decode(
    syndrome_bits: list[int],
    mask_bits: list[int],
    y: QArray[QBit],
    solution: QArray[QBit],
) -> None:
    for entry in range(22):
        for bit in range(6):
            if syndrome_bits[6 * entry + bit] == 0:
                X(solution[bit])
        for bit in range(6):
            if mask_bits[6 * entry + bit] == 1:
                controlled_flip(solution, y[bit])
        for bit in range(6):
            if syndrome_bits[6 * entry + bit] == 0:
                X(solution[bit])


@qfunc
def main(
    amplitudes: list[float],
    matrix: list[int],
    signs: list[int],
    syndrome_bits: list[int],
    mask_bits: list[int],
    y: Output[QArray[QBit]],
    solution: Output[QArray[QBit]],
) -> None:
    allocate(6, y)
    allocate(6, solution)
    inplace_prepare_amplitudes(amplitudes, 0, y)
    for bit in range(6):
        phase(y[bit], math.pi * signs[bit])
    gf2_product(matrix, y, solution)
    decode(syndrome_bits, mask_bits, y, solution)
    for bit in range(6):
        H(solution[bit])


def symmetric_amplitudes(weights: tuple[float, ...]) -> list[float]:
    """Embed the retained weight-zero/one/two superposition into six bits."""
    if len(weights) != 4 or any(
        type(value) not in (int, float) or abs(value) > 1 or not math.isfinite(value)
        for value in weights
    ):
        raise ValueError("weights must be four finite real amplitudes in [-1, 1]")
    if weights[3] != 0:
        raise ValueError("the retained decoder supports weight zero through two only")
    if not math.isclose(
        math.fsum(value * value for value in weights), 1, rel_tol=0, abs_tol=1e-12
    ):
        raise ValueError("weight amplitudes must be normalized")
    return [
        weights[k] / math.sqrt(math.comb(6, k)) if k <= 2 else 0.0
        for word in range(64)
        for k in (word.bit_count(),)
    ]


def build_program(weights: tuple[float, ...] = WEIGHTS) -> synth.Program:
    return synth.synthesize(
        main,
        classical_inputs={
            "amplitudes": symmetric_amplitudes(weights),
            "matrix": [
                (column >> row) & 1 for row in range(6) for column in PARITY_COLUMNS
            ],
            "signs": list(SIGNS),
            "syndrome_bits": [
                (word >> bit) & 1 for word, _ in SYNDROME_TABLE for bit in range(6)
            ],
            "mask_bits": [
                (mask >> bit) & 1 for _, mask in SYNDROME_TABLE for bit in range(6)
            ],
        },
        max_qubits=15,
        max_workspace=3,
        memory_limit_bytes=64 * 1024**2,
    )


if __name__ == "__main__":
    program = build_program()
    result = fq.run(program)
    print(dict(program.probabilities(result, registers=("y", "solution"))))
    print(program.report["resources"])
